/// `MCR_A1`.
///
/// Cut: CP, ConditionPassed, FORM, REG, _PC.
pub(super) fn MCR_A1(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::MCR_A1;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = (w >> 21) & 0x7;
    let s2: u128 = (w >> 16) & 0xf;
    let s3: u128 = (w >> 12) & 0xf;
    let s4: u128 = (w >> 8) & 0x1;
    let s5: u128 = (w >> 5) & 0x7;
    let s6: u128 = (w >> 0) & 0xf;
    st.cond_guard(b, ((w >> 28) & 0xf));
    let s7: u128 = (s4 << 3) | s1;
    let s8: u128 = (s7 << 4) | s2;
    let s9: u128 = (s8 << 4) | s6;
    let s10: u128 = (s9 << 3) | s5;
    let s11: i128 = s3 as i128;
    let s12: bool = s11 == (15i128);
    let s13: u128 = (pc >> 0) & 0xffffffff;
    let s14: u128 = s13.wrapping_add(0x8u128) & 0xffffffff;
    let v16 = st.r_read(b, s11 as u32);
    let v17 = b.konst(Width::new(32), s14);
    let v18 = if s12 { v17 } else { v16 };
    st.cp_write(b, ((s10) as u32), v18, None);
    Ok(())
}

/// `MRC_A1`.
