    let s8: u128 = (s7 << 4) | s2;
    let s9: u128 = (s8 << 4) | s6;
    let s10: u128 = (s9 << 3) | s5;
    let v11 = st.cp_read(b, ((s10) as u32));
    let s12: bool = s3 == 0xfu128;
